public class LdDeliveryServiceImpl implements LdDeliveryService {
 private final LdConsolidatedPlanRepository plans;private final LdConsolidatedPlanSourceRepository planSources;private final LdProgramRepository programs;private final LdProgramSourceRepository programSources;private final LdOfferingRepository offerings;private final LdOfferingSessionRepository sessions;private final LdOfferingResourceRepository offeringResources;
 private final LdGovernancePolicyVersionRepository policies;private final LdInterventionVersionRepository interventions;private final LdEvaluationFrameworkVersionRepository frameworks;private final LdProviderRepository providers;private final LdResourcePersonRepository resourcePersons;private final LdIndividualDevelopmentPlanRepository idps;private final LdIndividualDevelopmentPlanItemRepository idpItems;private final LdLearningNeedRepository needs;
 private final HumanResourceAssessmentSubjectClient hr;private final AdministrativePerformancePlanningClient admin;private final PrimeHrAuditService audit;
 public LdDeliveryServiceImpl(LdConsolidatedPlanRepository plans,LdConsolidatedPlanSourceRepository planSources,LdProgramRepository programs,LdProgramSourceRepository programSources,LdOfferingRepository offerings,LdOfferingSessionRepository sessions,LdOfferingResourceRepository offeringResources,LdGovernancePolicyVersionRepository policies,LdInterventionVersionRepository interventions,LdEvaluationFrameworkVersionRepository frameworks,LdProviderRepository providers,LdResourcePersonRepository resourcePersons,LdIndividualDevelopmentPlanRepository idps,LdIndividualDevelopmentPlanItemRepository idpItems,LdLearningNeedRepository needs,HumanResourceAssessmentSubjectClient hr,AdministrativePerformancePlanningClient admin,PrimeHrAuditService audit){this.plans=plans;this.planSources=planSources;this.programs=programs;this.programSources=programSources;this.offerings=offerings;this.sessions=sessions;this.offeringResources=offeringResources;this.policies=policies;this.interventions=interventions;this.frameworks=frameworks;this.providers=providers;this.resourcePersons=resourcePersons;this.idps=idps;this.idpItems=idpItems;this.needs=needs;this.hr=hr;this.admin=admin;this.audit=audit;}

 @Override @Transactional(readOnly=true)public List<PlanResponse>plans(String agency,String actor,PermissionDataScope scope){return plans.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(p->visible(p.getAccountableEmployeeNo(),actor,scope)).map(p->planResponse(agency,p)).toList();}
 @Override @Transactional(readOnly=true)public PlanResponse plan(String agency,String id,String actor,PermissionDataScope scope){LdConsolidatedPlan p=plan(agency,id);access(p.getAccountableEmployeeNo(),actor,scope);return planResponse(agency,p);}
 @Override public PlanResponse createPlan(String agency,PlanCreate in,String token,String actor,PermissionDataScope scope,String correlation){HumanResourceAssessmentSubject accountable=hr.get(in.accountableEmployeeId(),token);access(accountable.employeeNo(),actor,scope);var organization=admin.organization(in.organizationType(),in.organizationId(),token);var membership=admin.membership(accountable.employeeId(),token);if(in.scopeType()==LdConsolidatedPlan.ScopeType.OFFICE&&!matchesOrganization(in.organizationType(),organization.id(),membership))throw new IllegalArgumentException("Accountable employee must belong to the office plan organization");LdGovernancePolicyVersion policy=policy(agency,in.policyVersionId());if(policy.getStatus()!=LdDefinitionStatus.PUBLISHED||!policy.effectiveOn(in.periodStart()))throw new IllegalArgumentException("L&D governance policy must be published and effective on the plan start date");if(plans.existsByAgencyIdAndScopeTypeAndOrganizationIdAndPlanningYearAndStatusIn(agency,in.scopeType(),organization.id(),in.planningYear(),List.of(LdConsolidatedPlan.Status.DRAFT,LdConsolidatedPlan.Status.SUBMITTED,LdConsolidatedPlan.Status.APPROVED,LdConsolidatedPlan.Status.PUBLISHED)))throw new OptimisticConflictException("An active L&D plan already exists for this scope and planning year");LdConsolidatedPlan p=plans.saveAndFlush(new LdConsolidatedPlan(agency,in.scopeType(),in.organizationType(),organization.id(),organization.code(),organization.name(),organization.areaId(),organization.areaName(),organization.sourceFingerprint(),policy.getId(),policyFingerprint(policy),in.planningYear(),in.title(),in.objectives(),in.periodStart(),in.periodEnd(),in.estimatedCost(),in.fundingSource(),accountable.employeeId(),accountable.employeeNo(),accountable.displayName(),accountable.appointmentId(),accountable.sourceFingerprint()));PlanResponse out=planResponse(agency,p);record(agency,"CREATE_LD_CONSOLIDATED_PLAN","LD_CONSOLIDATED_PLAN",p.getId(),p.getPlanVersion(),p.getVersion(),null,out,null,correlation);return out;}
 @Override public PlanResponse updatePlan(String agency,String id,PlanUpdate in,String actor,PermissionDataScope scope,String correlation){LdConsolidatedPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());PlanResponse before=planResponse(agency,p);p.update(in.title(),in.objectives(),in.periodStart(),in.periodEnd(),in.estimatedCost(),in.fundingSource());p=plans.saveAndFlush(p);return changedPlan(agency,p,"UPDATE_LD_CONSOLIDATED_PLAN",before,null,correlation);}
 @Override public PlanResponse addPlanSource(String agency,String id,PlanSourceInput in,String token,String actor,PermissionDataScope scope,String correlation){LdConsolidatedPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());if(planSources.existsByAgencyIdAndPlanIdAndSourceTypeAndSourceId(agency,id,in.sourceType(),in.sourceId()))throw new OptimisticConflictException("Source is already consolidated in this plan");PlanResponse before=planResponse(agency,p);LdConsolidatedPlanSource source=in.sourceType()==LdConsolidatedPlanSource.SourceType.APPROVED_IDP_ITEM?idpSource(agency,p,in):organizationalSource(agency,p,in,token);planSources.saveAndFlush(source);p.touch();p=plans.saveAndFlush(p);return changedPlan(agency,p,"ADD_LD_PLAN_SOURCE",before,null,correlation);}
 @Override public PlanResponse removePlanSource(String agency,String id,String sourceId,Transition in,String actor,PermissionDataScope scope,String correlation){LdConsolidatedPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());LdConsolidatedPlanSource source=planSources.findByIdAndAgencyIdAndPlanId(sourceId,agency,id).orElseThrow(()->new ResourceNotFoundException("L&D plan source not found"));PlanResponse before=planResponse(agency,p);planSources.delete(source);planSources.flush();p.touch();p=plans.saveAndFlush(p);return changedPlan(agency,p,"REMOVE_LD_PLAN_SOURCE",before,in.reason(),correlation);}
 @Override public PlanResponse submitPlan(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdConsolidatedPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());if(planSources.findByAgencyIdAndPlanIdOrderByDisplayOrderAsc(agency,id).isEmpty())throw new IllegalArgumentException("L&D plan requires at least one authorized source");PlanResponse before=planResponse(agency,p);p.submit(actor,Instant.now());p=plans.saveAndFlush(p);return changedPlan(agency,p,"SUBMIT_LD_CONSOLIDATED_PLAN",before,in.reason(),correlation);}
 @Override public PlanResponse approvePlan(String agency,String id,Transition in,String token,String actor,PermissionDataScope scope,String correlation){agencyWide(scope,"L&D plan approval");LdConsolidatedPlan p=plan(agency,id);check(p.getVersion(),in.recordVersion());if(actor.equalsIgnoreCase(p.getSubmittedBy())||actor.equalsIgnoreCase(p.getAccountableEmployeeNo()))throw new AccessDeniedException("L&D plan approver must be independent from its submitter and accountable employee");HumanResourceAssessmentSubject current=hr.get(p.getAccountableEmployeeId(),token);if(!Objects.equals(current.appointmentId(),p.getAccountableAppointmentId())||!Objects.equals(current.sourceFingerprint(),p.getAccountableFingerprint()))throw new OptimisticConflictException("Accountable employee appointment changed; revise the plan snapshot");PlanResponse before=planResponse(agency,p);p.approve(actor,Instant.now());p=plans.saveAndFlush(p);return changedPlan(agency,p,"APPROVE_LD_CONSOLIDATED_PLAN",before,in.reason(),correlation);}
 @Override public PlanResponse publishPlan(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){agencyWide(scope,"L&D plan publication");LdConsolidatedPlan p=plan(agency,id);check(p.getVersion(),in.recordVersion());PlanResponse before=planResponse(agency,p);p.publish(actor,Instant.now());p=plans.saveAndFlush(p);return changedPlan(agency,p,"PUBLISH_LD_CONSOLIDATED_PLAN",before,in.reason(),correlation);}
 @Override public PlanResponse cancelPlan(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdConsolidatedPlan p=ownedPlan(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());PlanResponse before=planResponse(agency,p);p.cancel();p=plans.saveAndFlush(p);return changedPlan(agency,p,"CANCEL_LD_CONSOLIDATED_PLAN",before,in.reason(),correlation);}
 @Override public PlanResponse revisePlan(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdConsolidatedPlan prior=ownedPlan(agency,id,actor,scope);check(prior.getVersion(),in.recordVersion());LdConsolidatedPlan next=plans.saveAndFlush(prior.successor());for(var s:planSources.findByAgencyIdAndPlanIdOrderByDisplayOrderAsc(agency,id))planSources.save(copyPlanSource(agency,next.getId(),s));planSources.flush();PlanResponse out=planResponse(agency,next);record(agency,"REVISE_LD_CONSOLIDATED_PLAN","LD_CONSOLIDATED_PLAN",next.getId(),next.getPlanVersion(),next.getVersion(),planResponse(agency,prior),out,in.reason(),correlation);return out;}

 @Override @Transactional(readOnly=true)public List<ProgramResponse>programs(String agency,String actor,PermissionDataScope scope){return programs.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(p->visible(p.getAccountableEmployeeNo(),actor,scope)).map(p->programResponse(agency,p)).toList();}
 @Override @Transactional(readOnly=true)public ProgramResponse program(String agency,String id,String actor,PermissionDataScope scope){LdProgram p=program(agency,id);access(p.getAccountableEmployeeNo(),actor,scope);return programResponse(agency,p);}
 @Override public ProgramResponse createProgram(String agency,ProgramCreate in,String token,String actor,PermissionDataScope scope,String correlation){LdConsolidatedPlan plan=plan(agency,in.planId());if(plan.getStatus()!=LdConsolidatedPlan.Status.PUBLISHED)throw new IllegalStateException("Program design requires a PUBLISHED L&D plan");HumanResourceAssessmentSubject accountable=hr.get(in.accountableEmployeeId(),token);access(accountable.employeeNo(),actor,scope);LdInterventionVersion intervention=intervention(agency,in.interventionVersionId());LdEvaluationFrameworkVersion framework=framework(agency,in.evaluationFrameworkVersionId());publishedOn(intervention,in.scheduleStart(),"intervention");publishedOn(framework,in.scheduleStart(),"evaluation framework");inside(in.scheduleStart(),in.scheduleEnd(),plan.getPeriodStart(),plan.getPeriodEnd(),"Program schedule must remain inside the published plan period");if(programs.existsByAgencyIdAndNormalizedCodeAndProgramVersion(agency,in.code().trim().toUpperCase(Locale.ROOT),1))throw new IllegalArgumentException("L&D program code already exists");LdProgram p=programs.saveAndFlush(new LdProgram(agency,plan.getId(),plan.getPlanVersion(),planFingerprint(plan),in.code(),in.title(),intervention.getId(),interventionFingerprint(intervention),framework.getId(),frameworkFingerprint(framework),in.intendedOutcomes(),in.deliveryStrategy(),in.scheduleStart(),in.scheduleEnd(),in.estimatedHours(),in.estimatedCost(),in.fundingSource(),accountable.employeeId(),accountable.employeeNo(),accountable.displayName(),accountable.appointmentId(),accountable.sourceFingerprint()));ProgramResponse out=programResponse(agency,p);record(agency,"CREATE_LD_PROGRAM","LD_PROGRAM",p.getId(),p.getProgramVersion(),p.getVersion(),null,out,null,correlation);return out;}
 @Override public ProgramResponse updateProgram(String agency,String id,ProgramUpdate in,String actor,PermissionDataScope scope,String correlation){LdProgram p=ownedProgram(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());LdConsolidatedPlan plan=plan(agency,p.getPlanId());inside(in.scheduleStart(),in.scheduleEnd(),plan.getPeriodStart(),plan.getPeriodEnd(),"Program schedule must remain inside the approved plan period");ProgramResponse before=programResponse(agency,p);p.update(in.code(),in.title(),in.intendedOutcomes(),in.deliveryStrategy(),in.scheduleStart(),in.scheduleEnd(),in.estimatedHours(),in.estimatedCost(),in.fundingSource());p=programs.saveAndFlush(p);return changedProgram(agency,p,"UPDATE_LD_PROGRAM",before,null,correlation);}
 @Override public ProgramResponse addProgramSource(String agency,String id,ProgramSourceInput in,String actor,PermissionDataScope scope,String correlation){LdProgram p=ownedProgram(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());String planId=p.getPlanId();LdConsolidatedPlanSource source=planSources.findByIdAndAgencyId(in.planSourceId(),agency).filter(s->s.getPlanId().equals(planId)).orElseThrow(()->new ResourceNotFoundException("Approved plan source not found"));if(programSources.existsByAgencyIdAndProgramIdAndPlanSourceId(agency,id,source.getId()))throw new OptimisticConflictException("Plan source is already assigned to the program");ProgramResponse before=programResponse(agency,p);programSources.saveAndFlush(new LdProgramSource(agency,id,source.getId(),source.getSourceFingerprint(),source.getDevelopmentObjective(),source.getSuccessMeasure(),in.displayOrder()));p.touch();p=programs.saveAndFlush(p);return changedProgram(agency,p,"ADD_LD_PROGRAM_SOURCE",before,null,correlation);}
 @Override public ProgramResponse removeProgramSource(String agency,String id,String sourceId,Transition in,String actor,PermissionDataScope scope,String correlation){LdProgram p=ownedProgram(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());LdProgramSource source=programSources.findByIdAndAgencyIdAndProgramId(sourceId,agency,id).orElseThrow(()->new ResourceNotFoundException("L&D program source not found"));ProgramResponse before=programResponse(agency,p);programSources.delete(source);programSources.flush();p.touch();p=programs.saveAndFlush(p);return changedProgram(agency,p,"REMOVE_LD_PROGRAM_SOURCE",before,in.reason(),correlation);}
 @Override public ProgramResponse submitProgram(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdProgram p=ownedProgram(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());if(programSources.findByAgencyIdAndProgramIdOrderByDisplayOrderAsc(agency,id).isEmpty())throw new IllegalArgumentException("L&D program requires at least one approved-plan source");ProgramResponse before=programResponse(agency,p);p.submit(actor,Instant.now());p=programs.saveAndFlush(p);return changedProgram(agency,p,"SUBMIT_LD_PROGRAM",before,in.reason(),correlation);}
 @Override public ProgramResponse approveProgram(String agency,String id,Transition in,String token,String actor,PermissionDataScope scope,String correlation){agencyWide(scope,"L&D program approval");LdProgram p=program(agency,id);check(p.getVersion(),in.recordVersion());if(actor.equalsIgnoreCase(p.getSubmittedBy())||actor.equalsIgnoreCase(p.getAccountableEmployeeNo()))throw new AccessDeniedException("L&D program approver must be independent from its submitter and accountable employee");HumanResourceAssessmentSubject current=hr.get(p.getAccountableEmployeeId(),token);if(!Objects.equals(current.appointmentId(),p.getAccountableAppointmentId())||!Objects.equals(current.sourceFingerprint(),p.getAccountableFingerprint()))throw new OptimisticConflictException("Program accountable employee appointment changed; revise the program snapshot");ProgramResponse before=programResponse(agency,p);p.approve(actor,Instant.now());p=programs.saveAndFlush(p);return changedProgram(agency,p,"APPROVE_LD_PROGRAM",before,in.reason(),correlation);}
 @Override public ProgramResponse cancelProgram(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdProgram p=ownedProgram(agency,id,actor,scope);check(p.getVersion(),in.recordVersion());ProgramResponse before=programResponse(agency,p);p.cancel();p=programs.saveAndFlush(p);return changedProgram(agency,p,"CANCEL_LD_PROGRAM",before,in.reason(),correlation);}
 @Override public ProgramResponse reviseProgram(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdProgram prior=ownedProgram(agency,id,actor,scope);check(prior.getVersion(),in.recordVersion());LdProgram next=programs.saveAndFlush(prior.successor());for(var s:programSources.findByAgencyIdAndProgramIdOrderByDisplayOrderAsc(agency,id))programSources.save(new LdProgramSource(agency,next.getId(),s.getPlanSourceId(),s.getSourceFingerprint(),s.getDevelopmentObjective(),s.getSuccessMeasure(),s.getDisplayOrder()));programSources.flush();ProgramResponse out=programResponse(agency,next);record(agency,"REVISE_LD_PROGRAM","LD_PROGRAM",next.getId(),next.getProgramVersion(),next.getVersion(),programResponse(agency,prior),out,in.reason(),correlation);return out;}

 @Override @Transactional(readOnly=true)public List<OfferingResponse>offerings(String agency,String actor,PermissionDataScope scope){return offerings.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(o->visible(program(agency,o.getProgramId()).getAccountableEmployeeNo(),actor,scope)).map(o->offeringResponse(agency,o)).toList();}
 @Override @Transactional(readOnly=true)public OfferingResponse offering(String agency,String id,String actor,PermissionDataScope scope){LdOffering o=offering(agency,id);access(program(agency,o.getProgramId()).getAccountableEmployeeNo(),actor,scope);return offeringResponse(agency,o);}
 @Override public OfferingResponse createOffering(String agency,OfferingCreate in,String actor,PermissionDataScope scope,String correlation){LdProgram p=program(agency,in.programId());if(p.getStatus()!=LdProgram.Status.APPROVED)throw new IllegalStateException("Offering design requires an APPROVED L&D program");access(p.getAccountableEmployeeNo(),actor,scope);LdProvider provider=in.providerId()==null?null:provider(agency,in.providerId());if(provider!=null&&provider.getStatus()!=LdProvider.Status.ACTIVE)throw new IllegalArgumentException("Offering provider must be active");if(offerings.existsByAgencyIdAndNormalizedCodeAndOfferingVersion(agency,in.code().trim().toUpperCase(Locale.ROOT),1))throw new IllegalArgumentException("L&D offering code already exists");LdOffering o=offerings.saveAndFlush(new LdOffering(agency,p.getId(),p.getProgramVersion(),programFingerprint(p),in.code(),in.title(),in.modality(),in.venueOrPlatform(),in.capacity(),provider==null?null:provider.getId(),provider==null?null:provider.getName(),provider==null?null:providerFingerprint(provider),p.getEvaluationFrameworkVersionId(),p.getEvaluationFingerprint(),in.approvedBudget(),in.fundingSource(),in.currencyCode(),in.registrationOpen(),in.registrationClose()));OfferingResponse out=offeringResponse(agency,o);record(agency,"CREATE_LD_OFFERING","LD_OFFERING",o.getId(),o.getOfferingVersion(),o.getVersion(),null,out,null,correlation);return out;}
 @Override public OfferingResponse updateOffering(String agency,String id,OfferingUpdate in,String actor,PermissionDataScope scope,String correlation){LdOffering o=ownedOffering(agency,id,actor,scope);check(o.getVersion(),in.recordVersion());OfferingResponse before=offeringResponse(agency,o);o.update(in.code(),in.title(),in.modality(),in.venueOrPlatform(),in.capacity(),in.approvedBudget(),in.fundingSource(),in.currencyCode(),in.registrationOpen(),in.registrationClose());o=offerings.saveAndFlush(o);return changedOffering(agency,o,"UPDATE_LD_OFFERING",before,null,correlation);}
 @Override public OfferingResponse replaceSessions(String agency,String id,SessionsInput in,String actor,PermissionDataScope scope,String correlation){LdOffering o=ownedOffering(agency,id,actor,scope);check(o.getVersion(),in.recordVersion());LdProgram p=program(agency,o.getProgramId());validateSessions(in,p);OfferingResponse before=offeringResponse(agency,o);sessions.deleteAll(sessions.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(agency,id));sessions.flush();sessions.saveAll(in.sessions().stream().map(s->new LdOfferingSession(agency,id,s.title(),s.startsAt(),s.endsAt(),s.venueOrPlatform(),s.creditedHours(),s.displayOrder())).toList());sessions.flush();o.touch();o=offerings.saveAndFlush(o);return changedOffering(agency,o,"REPLACE_LD_OFFERING_SESSIONS",before,null,correlation);}
 @Override public OfferingResponse replaceResources(String agency,String id,ResourcesInput in,String actor,PermissionDataScope scope,String correlation){LdOffering o=ownedOffering(agency,id,actor,scope);check(o.getVersion(),in.recordVersion());Set<String> unique=new HashSet<>();List<LdOfferingResource> replacements=new ArrayList<>();for(ResourceInput row:in.resources()==null?List.<ResourceInput>of():in.resources()){String key=row.resourcePersonId()+"|"+row.role();if(!unique.add(key))throw new IllegalArgumentException("Duplicate offering resource and role");LdResourcePerson person=resourcePerson(agency,row.resourcePersonId());if(person.getStatus()!=LdResourcePerson.Status.ACTIVE)throw new IllegalArgumentException("Offering resources must be active");replacements.add(resourceSnapshot(agency,id,row,person));}OfferingResponse before=offeringResponse(agency,o);offeringResources.deleteAll(offeringResources.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(agency,id));offeringResources.flush();offeringResources.saveAll(replacements);offeringResources.flush();o.touch();o=offerings.saveAndFlush(o);return changedOffering(agency,o,"REPLACE_LD_OFFERING_RESOURCES",before,null,correlation);}
 @Override public OfferingResponse submitOffering(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdOffering o=ownedOffering(agency,id,actor,scope);check(o.getVersion(),in.recordVersion());validateOfferingReady(agency,o);OfferingResponse before=offeringResponse(agency,o);o.submit(actor,Instant.now());o=offerings.saveAndFlush(o);return changedOffering(agency,o,"SUBMIT_LD_OFFERING",before,in.reason(),correlation);}
 @Override public OfferingResponse approveOffering(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){agencyWide(scope,"L&D offering approval");LdOffering o=offering(agency,id);check(o.getVersion(),in.recordVersion());LdProgram p=program(agency,o.getProgramId());if(actor.equalsIgnoreCase(o.getSubmittedBy())||actor.equalsIgnoreCase(p.getAccountableEmployeeNo()))throw new AccessDeniedException("Offering approver must be independent from its submitter and accountable employee");validateOfferingReady(agency,o);OfferingResponse before=offeringResponse(agency,o);o.approve(actor,Instant.now());o=offerings.saveAndFlush(o);return changedOffering(agency,o,"APPROVE_LD_OFFERING",before,in.reason(),correlation);}
 @Override public OfferingResponse publishOffering(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){agencyWide(scope,"L&D offering publication");LdOffering o=offering(agency,id);check(o.getVersion(),in.recordVersion());validateOfferingReady(agency,o);validateCurrentRegistries(agency,o);OfferingResponse before=offeringResponse(agency,o);o.publish(actor,Instant.now());o=offerings.saveAndFlush(o);return changedOffering(agency,o,"PUBLISH_LD_OFFERING",before,in.reason(),correlation);}
 @Override public OfferingResponse cancelOffering(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdOffering o=ownedOffering(agency,id,actor,scope);check(o.getVersion(),in.recordVersion());OfferingResponse before=offeringResponse(agency,o);o.cancel();o=offerings.saveAndFlush(o);return changedOffering(agency,o,"CANCEL_LD_OFFERING",before,in.reason(),correlation);}
 @Override public OfferingResponse reviseOffering(String agency,String id,Transition in,String actor,PermissionDataScope scope,String correlation){LdOffering prior=ownedOffering(agency,id,actor,scope);check(prior.getVersion(),in.recordVersion());LdOffering next=offerings.saveAndFlush(prior.successor());for(var s:sessions.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(agency,id))sessions.save(new LdOfferingSession(agency,next.getId(),s.getTitle(),s.getStartsAt(),s.getEndsAt(),s.getVenueOrPlatform(),s.getCreditedHours(),s.getDisplayOrder()));for(var r:offeringResources.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(agency,id))offeringResources.save(new LdOfferingResource(agency,next.getId(),r.getResourcePersonId(),r.getRole(),r.getPersonCode(),r.getPersonSource(),r.getEmployeeNo(),r.getDisplayName(),r.getProviderId(),r.getExpertise(),r.getCredentials(),r.getResourceFingerprint(),r.getDisplayOrder()));sessions.flush();offeringResources.flush();OfferingResponse out=offeringResponse(agency,next);record(agency,"REVISE_LD_OFFERING","LD_OFFERING",next.getId(),next.getOfferingVersion(),next.getVersion(),offeringResponse(agency,prior),out,in.reason(),correlation);return out;}

 private LdConsolidatedPlanSource idpSource(String agency,LdConsolidatedPlan plan,PlanSourceInput in){LdIndividualDevelopmentPlanItem item=idpItems.findByIdAndAgencyId(in.sourceId(),agency).orElseThrow(()->new ResourceNotFoundException("IDP item not found"));LdIndividualDevelopmentPlan idp=idps.findByIdAndAgencyId(item.getPlanId(),agency).orElseThrow(()->new ResourceNotFoundException("IDP not found"));if(idp.getStatus()!=LdIndividualDevelopmentPlan.Status.APPROVED)throw new IllegalStateException("Only an APPROVED IDP item may be consolidated");Long organizationId=plan.getOrganizationType().equals("AREA")?idp.getAreaId():idp.getBusinessUnitId();String organizationName=plan.getOrganizationType().equals("AREA")?idp.getAreaName():idp.getBusinessUnitName();if(plan.getScopeType()==LdConsolidatedPlan.ScopeType.OFFICE&&!plan.getOrganizationId().equals(organizationId))throw new IllegalArgumentException("IDP item is outside the office plan organization");return new LdConsolidatedPlanSource(agency,plan.getId(),in.sourceType(),item.getId(),item.getVersion(),idpItemFingerprint(item),idp.getEmployeeNo(),organizationId,organizationName,item.getDevelopmentObjective(),item.getSuccessMeasure(),item.getTargetDate(),item.getPriority(),in.displayOrder());}
 private LdConsolidatedPlanSource organizationalSource(String agency,LdConsolidatedPlan plan,PlanSourceInput in,String token){LdLearningNeed need=needs.findByIdAndAgencyId(in.sourceId(),agency).orElseThrow(()->new ResourceNotFoundException("Organizational learning need not found"));if(need.getSourceType()!=LearningNeedSourceType.ORGANIZATIONAL_NEED||need.getStatus()==LdLearningNeed.Status.CANCELLED)throw new IllegalArgumentException("Source must be an active ORGANIZATIONAL_NEED");var membership=admin.membership(need.getEmployeeId(),token);Long organizationId=plan.getOrganizationType().equals("AREA")?membership.areaId():membership.businessUnitId();String organizationName=plan.getOrganizationType().equals("AREA")?membership.areaName():membership.businessUnitName();if(plan.getScopeType()==LdConsolidatedPlan.ScopeType.OFFICE&&!plan.getOrganizationId().equals(organizationId))throw new IllegalArgumentException("Organizational need is outside the office plan organization");return new LdConsolidatedPlanSource(agency,plan.getId(),in.sourceType(),need.getId(),need.getVersion(),needFingerprint(need),need.getEmployeeNo(),organizationId,organizationName,need.getDevelopmentObjective(),need.getSuccessMeasure(),need.getTargetDate(),need.getPriority(),in.displayOrder());}
 private LdConsolidatedPlanSource copyPlanSource(String agency,String planId,LdConsolidatedPlanSource s){return new LdConsolidatedPlanSource(agency,planId,s.getSourceType(),s.getSourceId(),s.getSourceVersion(),s.getSourceFingerprint(),s.getEmployeeNo(),s.getOrganizationId(),s.getOrganizationName(),s.getDevelopmentObjective(),s.getSuccessMeasure(),s.getTargetDate(),s.getPriority(),s.getDisplayOrder());}
 private void validateSessions(SessionsInput in,LdProgram program){List<SessionInput> ordered=new ArrayList<>(in.sessions());ordered.sort(Comparator.comparing(SessionInput::startsAt));Set<Integer> display=new HashSet<>();for(int i=0;i<ordered.size();i++){SessionInput s=ordered.get(i);if(!display.add(s.displayOrder()))throw new IllegalArgumentException("Session displayOrder must be unique");LocalDate start=s.startsAt().toLocalDate(),end=s.endsAt().toLocalDate();inside(start,end,program.getScheduleStart(),program.getScheduleEnd(),"Offering sessions must remain inside the approved program window");if(i>0&&s.startsAt().isBefore(ordered.get(i-1).endsAt()))throw new IllegalArgumentException("Offering sessions cannot overlap");}}
 private void validateOfferingReady(String agency,LdOffering o){if(sessions.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(agency,o.getId()).isEmpty())throw new IllegalArgumentException("Offering requires at least one session");boolean facilitator=offeringResources.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(agency,o.getId()).stream().anyMatch(r->r.getRole()==LdOfferingResource.Role.LEAD_FACILITATOR||r.getRole()==LdOfferingResource.Role.RESOURCE_PERSON);if(!facilitator)throw new IllegalArgumentException("Offering requires a lead facilitator or resource person");}
 private void validateCurrentRegistries(String agency,LdOffering o){if(o.getProviderId()!=null){LdProvider p=provider(agency,o.getProviderId());if(p.getStatus()!=LdProvider.Status.ACTIVE||!providerFingerprint(p).equals(o.getProviderFingerprint()))throw new OptimisticConflictException("Offering provider changed or became inactive; create a current offering revision");}for(var snapshot:offeringResources.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(agency,o.getId())){LdResourcePerson current=resourcePerson(agency,snapshot.getResourcePersonId());if(current.getStatus()!=LdResourcePerson.Status.ACTIVE||!resourceFingerprint(current).equals(snapshot.getResourceFingerprint()))throw new OptimisticConflictException("Offering resource person changed or became inactive; create a current offering revision");}}
 private LdOfferingResource resourceSnapshot(String agency,String offering,ResourceInput row,LdResourcePerson p){return new LdOfferingResource(agency,offering,p.getId(),row.role(),p.getCode(),p.getPersonSource().name(),p.getEmployeeNo(),p.getDisplayName(),p.getProviderId(),p.getExpertise(),p.getCredentials(),resourceFingerprint(p),row.displayOrder());}
 private LdConsolidatedPlan ownedPlan(String a,String id,String actor,PermissionDataScope scope){LdConsolidatedPlan p=plan(a,id);access(p.getAccountableEmployeeNo(),actor,scope);return p;}private LdProgram ownedProgram(String a,String id,String actor,PermissionDataScope scope){LdProgram p=program(a,id);access(p.getAccountableEmployeeNo(),actor,scope);return p;}private LdOffering ownedOffering(String a,String id,String actor,PermissionDataScope scope){LdOffering o=offering(a,id);access(program(a,o.getProgramId()).getAccountableEmployeeNo(),actor,scope);return o;}
 private static boolean visible(String accountable,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.ASSIGNED_RECORDS&&accountable.equalsIgnoreCase(actor);}private static void access(String accountable,String actor,PermissionDataScope scope){if(!visible(accountable,actor,scope))throw new AccessDeniedException("L&D record is outside the permitted scope");}private static void agencyWide(PermissionDataScope scope,String action){if(scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException(action+" requires agency-wide permission");}
 private static boolean matchesOrganization(String type,Long id,AdministrativePerformancePlanningClient.PersonnelMembership m){return type.equalsIgnoreCase("AREA")?Objects.equals(id,m.areaId()):Objects.equals(id,m.businessUnitId());}private static void inside(LocalDate start,LocalDate end,LocalDate min,LocalDate max,String message){if(start==null||end==null||end.isBefore(start)||start.isBefore(min)||end.isAfter(max))throw new IllegalArgumentException(message);}
 private static void publishedOn(LdVersionedDefinition d,LocalDate date,String label){if(d.getStatus()!=LdDefinitionStatus.PUBLISHED||!d.effectiveOn(date))throw new IllegalArgumentException("Published "+label+" must be effective on the program start date");}
 private LdConsolidatedPlan plan(String a,String id){return plans.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D plan not found"));}private LdProgram program(String a,String id){return programs.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D program not found"));}private LdOffering offering(String a,String id){return offerings.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D offering not found"));}private LdGovernancePolicyVersion policy(String a,String id){return policies.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D governance policy not found"));}private LdInterventionVersion intervention(String a,String id){return interventions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D intervention not found"));}private LdEvaluationFrameworkVersion framework(String a,String id){return frameworks.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D evaluation framework not found"));}private LdProvider provider(String a,String id){return providers.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D provider not found"));}private LdResourcePerson resourcePerson(String a,String id){return resourcePersons.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("L&D resource person not found"));}
 private PlanResponse planResponse(String a,LdConsolidatedPlan p){List<PlanSourceResponse> source=planSources.findByAgencyIdAndPlanIdOrderByDisplayOrderAsc(a,p.getId()).stream().map(s->new PlanSourceResponse(s.getId(),s.getSourceType().name(),s.getSourceId(),s.getSourceVersion(),s.getSourceFingerprint(),s.getEmployeeNo(),s.getOrganizationId(),s.getOrganizationName(),s.getDevelopmentObjective(),s.getSuccessMeasure(),s.getTargetDate(),s.getPriority(),s.getDisplayOrder())).toList();return new PlanResponse(p.getId(),p.getSeriesId(),p.getPlanVersion(),p.getSupersedesId(),p.getScopeType().name(),p.getOrganizationType(),p.getOrganizationId(),p.getOrganizationCode(),p.getOrganizationName(),p.getAreaId(),p.getAreaName(),p.getOrganizationFingerprint(),p.getPolicyVersionId(),p.getPolicyFingerprint(),p.getPlanningYear(),p.getTitle(),p.getObjectives(),p.getPeriodStart(),p.getPeriodEnd(),p.getEstimatedCost(),p.getFundingSource(),p.getAccountableEmployeeId(),p.getAccountableEmployeeNo(),p.getAccountableName(),p.getAccountableAppointmentId(),p.getAccountableFingerprint(),p.getStatus().name(),p.getContentRevision(),p.getVersion(),p.getSubmittedBy(),p.getSubmittedAt(),p.getApprovedBy(),p.getApprovedAt(),p.getPublishedBy(),p.getPublishedAt(),source);}
 private ProgramResponse programResponse(String a,LdProgram p){List<ProgramSourceResponse> source=programSources.findByAgencyIdAndProgramIdOrderByDisplayOrderAsc(a,p.getId()).stream().map(s->new ProgramSourceResponse(s.getId(),s.getPlanSourceId(),s.getSourceFingerprint(),s.getDevelopmentObjective(),s.getSuccessMeasure(),s.getDisplayOrder())).toList();return new ProgramResponse(p.getId(),p.getSeriesId(),p.getProgramVersion(),p.getSupersedesId(),p.getPlanId(),p.getPlanVersion(),p.getPlanFingerprint(),p.getCode(),p.getTitle(),p.getInterventionVersionId(),p.getInterventionFingerprint(),p.getEvaluationFrameworkVersionId(),p.getEvaluationFingerprint(),p.getIntendedOutcomes(),p.getDeliveryStrategy(),p.getScheduleStart(),p.getScheduleEnd(),p.getEstimatedHours(),p.getEstimatedCost(),p.getFundingSource(),p.getAccountableEmployeeId(),p.getAccountableEmployeeNo(),p.getAccountableName(),p.getAccountableAppointmentId(),p.getAccountableFingerprint(),p.getStatus().name(),p.getContentRevision(),p.getVersion(),p.getSubmittedBy(),p.getSubmittedAt(),p.getApprovedBy(),p.getApprovedAt(),source);}
 private OfferingResponse offeringResponse(String a,LdOffering o){List<SessionResponse> ss=sessions.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(a,o.getId()).stream().map(s->new SessionResponse(s.getId(),s.getTitle(),s.getStartsAt(),s.getEndsAt(),s.getVenueOrPlatform(),s.getCreditedHours(),s.getDisplayOrder())).toList();List<ResourceResponse> rs=offeringResources.findByAgencyIdAndOfferingIdOrderByDisplayOrderAsc(a,o.getId()).stream().map(r->new ResourceResponse(r.getId(),r.getResourcePersonId(),r.getRole().name(),r.getPersonCode(),r.getPersonSource(),r.getEmployeeNo(),r.getDisplayName(),r.getProviderId(),r.getExpertise(),r.getCredentials(),r.getResourceFingerprint(),r.getDisplayOrder())).toList();return new OfferingResponse(o.getId(),o.getSeriesId(),o.getOfferingVersion(),o.getSupersedesId(),o.getProgramId(),o.getProgramVersion(),o.getProgramFingerprint(),o.getCode(),o.getTitle(),o.getModality().name(),o.getVenueOrPlatform(),o.getCapacity(),o.getProviderId(),o.getProviderName(),o.getProviderFingerprint(),o.getEvaluationFrameworkVersionId(),o.getEvaluationFingerprint(),o.getApprovedBudget(),o.getFundingSource(),o.getCurrencyCode(),o.getRegistrationOpen(),o.getRegistrationClose(),o.getStatus().name(),o.getContentRevision(),o.getVersion(),o.getSubmittedBy(),o.getSubmittedAt(),o.getApprovedBy(),o.getApprovedAt(),o.getPublishedBy(),o.getPublishedAt(),ss,rs);}
 private PlanResponse changedPlan(String a,LdConsolidatedPlan p,String action,PlanResponse before,String reason,String c){PlanResponse out=planResponse(a,p);record(a,action,"LD_CONSOLIDATED_PLAN",p.getId(),p.getPlanVersion(),p.getVersion(),before,out,reason,c);return out;}private ProgramResponse changedProgram(String a,LdProgram p,String action,ProgramResponse before,String reason,String c){ProgramResponse out=programResponse(a,p);record(a,action,"LD_PROGRAM",p.getId(),p.getProgramVersion(),p.getVersion(),before,out,reason,c);return out;}private OfferingResponse changedOffering(String a,LdOffering o,String action,OfferingResponse before,String reason,String c){OfferingResponse out=offeringResponse(a,o);record(a,action,"LD_OFFERING",o.getId(),o.getOfferingVersion(),o.getVersion(),before,out,reason,c);return out;}
 private void record(String a,String action,String type,String id,Integer business,long version,Object before,Object after,String reason,String c){audit.record(a,action,type,id,business,version,before,after,reason,c);}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}
 private static String policyFingerprint(LdGovernancePolicyVersion p){return hash(p.getId(),p.getDefinitionVersion(),p.getTitle(),p.getLegalBasis(),p.getEffectiveFrom(),p.getEffectiveTo());}private static String interventionFingerprint(LdInterventionVersion i){return hash(i.getId(),i.getDefinitionVersion(),i.getTitle(),i.getCategory(),i.getDefaultModality(),i.getIntendedOutcomes(),i.getEffectiveFrom(),i.getEffectiveTo());}private static String frameworkFingerprint(LdEvaluationFrameworkVersion f){return hash(f.getId(),f.getDefinitionVersion(),f.getTitle(),f.getLegalBasis(),f.getLevelRevision(),f.getEffectiveFrom(),f.getEffectiveTo());}private static String providerFingerprint(LdProvider p){return hash(p.getId(),p.getVersion(),p.getCode(),p.getName(),p.getProviderType(),p.getAccreditationReference());}private static String resourceFingerprint(LdResourcePerson p){return hash(p.getId(),p.getVersion(),p.getCode(),p.getPersonSource(),p.getEmployeeNo(),p.getDisplayName(),p.getProviderId(),p.getExpertise(),p.getCredentials());}private static String planFingerprint(LdConsolidatedPlan p){return hash(p.getId(),p.getPlanVersion(),p.getContentRevision(),p.getStatus(),p.getOrganizationFingerprint(),p.getPolicyFingerprint(),p.getObjectives(),p.getPeriodStart(),p.getPeriodEnd(),p.getEstimatedCost(),p.getFundingSource());}private static String programFingerprint(LdProgram p){return hash(p.getId(),p.getProgramVersion(),p.getContentRevision(),p.getStatus(),p.getPlanFingerprint(),p.getInterventionFingerprint(),p.getEvaluationFingerprint(),p.getIntendedOutcomes(),p.getScheduleStart(),p.getScheduleEnd());}private static String idpItemFingerprint(LdIndividualDevelopmentPlanItem i){return hash(i.getId(),i.getVersion(),i.getLearningNeedId(),i.getSourceFingerprint(),i.getDevelopmentObjective(),i.getSuccessMeasure(),i.getTargetDate(),i.getPriority());}private static String needFingerprint(LdLearningNeed n){return hash(n.getId(),n.getVersion(),n.getSourceType(),n.getSourceReferenceId(),n.getSourceVersion(),n.getSourceFingerprint(),n.getDevelopmentObjective(),n.getSuccessMeasure(),n.getTargetDate(),n.getPriority());}
 private static String hash(Object... values){StringJoiner join=new StringJoiner("|");for(Object value:values)join.add(String.valueOf(value));try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(join.toString().getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
